CREATE TABLE orders_lab (id NUMBER PRIMARY KEY, status VARCHAR2(10));
INSERT INTO orders_lab VALUES (1001,'new');
COMMIT;
-- session A
UPDATE orders_lab SET status='paid' WHERE id=1001;
-- session B
UPDATE orders_lab SET status='shipped' WHERE id=1001;  -- waits

CREATE PLUGGABLE DATABASE ordersdev ADMIN USER pdbadmin IDENTIFIED BY "<password>"
  FILE_NAME_CONVERT = ('/pdbseed/', '/ordersdev/');
ALTER PLUGGABLE DATABASE ordersdev OPEN;
ALTER PLUGGABLE DATABASE ordersdev SAVE STATE;

STARTUP NOMOUNT;
ALTER DATABASE MOUNT;
ALTER DATABASE OPEN;

ALTER SYSTEM SET open_cursors=500 SCOPE=BOTH;
SELECT name, value FROM v$parameter WHERE name='open_cursors';
SELECT name, value FROM v$spparameter WHERE name='open_cursors';

SELECT sid, serial#, username, machine, program, service_name, server
  FROM v$session WHERE type='USER';
SELECT name, network_name FROM v$services;
SHOW PARAMETER local_listener

SELECT file_name, ROUND(bytes/1048576) mb, autoextensible,
       ROUND(maxbytes/1048576) max_mb, increment_by blocks_per_step
  FROM dba_data_files WHERE tablespace_name='USERS';

SELECT s.sid, s.username, u.tablespace, u.segtype, ROUND(u.blocks*8192/1048576) mb, u.sql_id
  FROM v$tempseg_usage u JOIN v$session s ON s.saddr=u.session_addr
 ORDER BY u.blocks DESC;

ALTER TABLE orders.order_lines ENABLE ROW MOVEMENT;
ALTER TABLE orders.order_lines SHRINK SPACE CASCADE;
ALTER TABLESPACE temp SHRINK SPACE KEEP 2G;
ALTER DATABASE DATAFILE '/u01/oradata/ORCL/orders01.dbf' RESIZE 20G;

CREATE ROLE orders_rw;
GRANT SELECT, INSERT, UPDATE ON orders.order_lines TO orders_rw;
CREATE USER orders_app IDENTIFIED BY "change-me-at-once" PROFILE svc_app;
GRANT CREATE SESSION, orders_rw TO orders_app;

CREATE AUDIT POLICY orders_ddl_pol ACTIONS CREATE TABLE, DROP TABLE, ALTER TABLE;
AUDIT POLICY orders_ddl_pol;
SELECT event_timestamp, dbusername, action_name, object_name
  FROM unified_audit_trail ORDER BY event_timestamp DESC FETCH FIRST 20 ROWS ONLY;

CONFIGURE RETENTION POLICY TO RECOVERY WINDOW OF 7 DAYS;
CONFIGURE CONTROLFILE AUTOBACKUP ON;
CONFIGURE DEVICE TYPE DISK PARALLELISM 2;
CONFIGURE BACKUP OPTIMIZATION ON;

RUN {
  BACKUP INCREMENTAL LEVEL 0 DATABASE TAG 'weekly0';
  BACKUP ARCHIVELOG ALL NOT BACKED UP 1 TIMES;
}
BACKUP INCREMENTAL LEVEL 1 DATABASE TAG 'daily1';
BACKUP ARCHIVELOG ALL NOT BACKED UP 1 TIMES;

CROSSCHECK BACKUP;
DELETE NOPROMPT OBSOLETE;
BACKUP VALIDATE CHECK LOGICAL DATABASE;
RESTORE DATABASE VALIDATE;

ALTER DATABASE FLASHBACK ON;
CREATE RESTORE POINT before_release GUARANTEE FLASHBACK DATABASE;
-- later, from MOUNT:
FLASHBACK DATABASE TO RESTORE POINT before_release;
ALTER DATABASE OPEN RESETLOGS;
DROP RESTORE POINT before_release;

RUN {
  ALTER PLUGGABLE DATABASE orders_pdb CLOSE;
  SET UNTIL TIME "TO_DATE('2026-10-12 09:40:00','YYYY-MM-DD HH24:MI:SS')";
  RESTORE PLUGGABLE DATABASE orders_pdb;
  RECOVER PLUGGABLE DATABASE orders_pdb;
  ALTER PLUGGABLE DATABASE orders_pdb OPEN RESETLOGS;
}

EXEC DBMS_MONITOR.SESSION_TRACE_ENABLE(session_id=>:sid, serial_num=>:serial, waits=>TRUE, binds=>FALSE);
-- later
EXEC DBMS_MONITOR.SESSION_TRACE_DISABLE(:sid, :serial);
